interface NorseIconProps {
  id: SystemId;
  className?: string;
  /** Accessible name. Without it the icon is decorative and hidden from assistive tech. */
  title?: string;
}

export default function NorseIcon({ id, className = "h-8 w-8", title }: NorseIconProps) {
  const labelled = title !== undefined && title !== "";
  return (
    <svg
      viewBox="0 0 32 32"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      className={`shrink-0 ${className}`}
      {...(labelled ? { role: "img" } : { "aria-hidden": true, focusable: "false" })}
    >
      {labelled ? <title>{title}</title> : null}
      {SHAPES[id]}
    </svg>
  );
}
